```sop
@slots literal
{"A": 5, "B": 3, "C": 3, "threshold": 6}

@answer jsEval
const groups = [["A", $slots.A], ["B", $slots.B], ["C", $slots.C]];
const threshold = $slots.threshold;
const subsets = [];
for (let mask = 1; mask < 8; mask++) {
  const members = groups.filter((_, index) => (mask & (1 << index)) !== 0);
  const seats = members.reduce((sum, group) => sum + group[1], 0);
  subsets.push({ names: members.map((group) => group[0]), seats });
}
const winning = subsets.filter((subset) => subset.seats >= threshold);
const minimal = winning.filter((subset) => subset.names.every((name) => {
  const remaining = subset.names.filter((member) => member !== name);
  const remainingSeats = remaining.reduce((sum, member) => sum + groups.find((group) => group[0] === member)[1], 0);
  return remainingSeats < threshold;
}));
return minimal.map((subset) => "{" + subset.names.join(", ") + "}").join(", ");
```

