```javascript
const seats = { A: 5, B: 3, C: 3 };
const threshold = 6;
const names = Object.keys(seats);
const subsets = [];
for (let mask = 1; mask < 8; mask++) {
  const members = names.filter((_, index) => (mask & (1 << index)) !== 0);
  const total = members.reduce((sum, name) => sum + seats[name], 0);
  subsets.push({ members, total });
}
const winning = subsets.filter((subset) => subset.total >= threshold);
const minimal = winning.filter((subset) => subset.members.every((name) => {
  const remaining = subset.members.filter((member) => member !== name);
  const remainingTotal = remaining.reduce((sum, member) => sum + seats[member], 0);
  return remainingTotal < threshold;
}));
return minimal.map((subset) => "{" + subset.members.join(", ") + "}").join(", ");
```

